case rnd.SETTINGS_ROW_NOC:
		// v2-noc player toggle: the availability flag (in-session only — the
		// persist below writes A11y_Settings, which does NOT carry noc_enabled;
		// a fresh launch starts ON again, the documented "fresh runs start
		// clean" choice). The D key itself is disabled while this is OFF.
		app.noc_enabled = !app.noc_enabled
---
effect_overlay :: proc(user: rawptr, ictx: ^inp.Input) {
	app := cast(^App)user
	if app.noc_enabled {
		app.overlay_on = !app.overlay_on
	}
}
---
		if app.overlay_on {
			if w := rl.GetMouseWheelMove(); w != 0 {
				app.noc_scroll = max(0, app.noc_scroll - i32(w))
			}
			if app.stats_valid {
				rnd.draw_noc_overlay(&app.view, &app.noc_feed, &app.stats, &app.state.topology, &app.state.bundles, &app.cat, app.state.events[:], app.input.sel_pipe, u32(len(app.state.flow.packets)), app.noc_scroll)
